  "who.valya": "Valentina, komşu",
  "who.marat": "Marat, Cosy Café şefi",
  "who.eduard": "Eduard, MegaMart müdürü",
  "who.inspector": "Belova, sağlık denetçisi",
  "story.chapter": "Bölüm {n}: {title}",
  "story.next": "İleri",
  "story.reward": "Ödül: {reward}",
  "story.goalLine": "📖 {title}: {goal}",
  "story.free": "📖 Serbest oyun: dükkânını büyütmeye devam et",
  "story.ch1.title": "Miras",
  "story.ch1.goal": "ninenin borcunu öde ({n} 💰 kaldı)",
  "story.ch1.intro1": "Merhaba! Ben ninen. Kardeşlerimin yanına, yazlığa taşındım; köşedeki büfemi sana bırakıyorum.",
  "story.ch1.intro2": "Defterimi sana mektupla göndereceğim — komşulara olan borcun hepsi orada yazılı. Lütfen onlara öde — insanlık bunu gerektirir.",
  "story.ch1.intro3": "Aa, artık tezgâhta sen varsın! Benim, Valentina, ninenin arkadaşı — hatırladın mı? Her gün ekmek almaya geleceğim!",
  "story.ch1.outro1": "Duydum, borcun hepsi ödenmiş! Ninen aradı — seninle gurur duyuyor.",
  "story.ch1.outro2": "Bu arada geçen gün Cosy Café'nin aşçısı Marat uğradı. Malzemeyi nereden alacağını arıyor…",
  "story.ch2.title": "Bizden biri",
  "story.ch2.goal": "2 sipariş tamamla ({n}/2) ve ilk çalışanını işe al ({staff})",
  "story.ch2.intro1": "Merhaba! Ben Marat, Cosy Café'nin şefi. Valentina fiyatlarınızın dürüst olduğunu söyledi.",
  "story.ch2.intro2": "Ara sıra akşama sipariş vereceğim. Beni yarı yolda bırakmayın — salonum hep dolu.",
  "story.ch2.outro1": "Sözünüzün eri çıktınız. Sizi tüm tanıdıklarıma önereceğim!",
  "story.ch3.title": "Rakip",
  "story.ch3.goal": "minimarket seviyesine ve 4★ puana ulaş (şu an {r}★). MegaMart müşterilerin bir kısmını çekiyor",
  "story.ch3.intro1": "Eduard, MegaMart müdürü. Tam karşınızda açılıyoruz.",
  "story.ch3.intro2": "Kırk kasamız ve her gün indirimimiz var. Tavsiyem: büfeyi hâlâ bir değeri varken satın.",
  "story.ch3.intro3": "Onu dinleme! Müdavimler bir yere gitmez… Gerçi bazıları elbet bir bakmaya gider.",
  "story.ch3.outro1": "Minimarket mi? Puanınız da bizimkinden yüksek? Hıh, göreceğiz…",
  "story.ch4.title": "Denetim",
  "story.ch4.goal": "2 denetimden geç ({n}/2)",
  "story.ch4.intro1": "Belova, sağlık denetimi. Hakkınızda şikâyet geldi.",
  "story.ch4.intro2": "Daha sık uğrayacağım. Çöp, kirli tuvalet, raflarda kusurlu ürün, ılık dolap — hepsini görürüm.",
  "story.ch4.intro3": "Şikâyet eden Eduard, sana söylüyorum!",
  "story.ch4.outro1": "Örnek bir dükkân. Raporuma da böyle yazacağım.",
  "story.ch4.outro2": "Hay Allah… Ben de bütün hafta ona söylenip durdum. Ona bir börek götüreyim — barışmak için.",
  "story.ch5.title": "Büyük mağaza",
  "story.ch5.goal": "büyük mağaza seviyesine ulaş",
  "story.ch5.intro1": "Yazlıktan arıyorum! Edik sana geliyormuş, duydum. Onu bir dinle, olur mu? İyi bir çocuktu o.",
  "story.ch5.intro2": "Borcumu getirdim. Ekmekler ve süt için — otuz yıllık, faiziyle. Lütfen alın.",
  "story.ch5.outro1": "Geldim. Dürüst olayım: yazlık bahaneydi. Sabah altıda uğruna kalkacağın birine ihtiyacın vardı.",
  "story.ch5.outro2": "Bütün mahalle artık bize geliyor. Eduard da, düşün, yanımızda büfe açmakla tehdit ediyor — “canım sıkılmasın diye”.",
