  "tip.new": "💡 Yeni",
  "tip.ok": "Anladım",
  "tip.weekly.title": "Haftanın görevleri",
  "tip.weekly.text": "Hafta için üç hedef — ilerleme gün gün birikir. Her biri tamamlanır tamamlanmaz ödülünü verir.",
  "tip.fair.title": "Panayır",
  "tip.fair.text": "Ayda bir kapının önünde panayır kurulur: tezgâh depodaki malı dörtte bir daha pahalıya satar — kasaya uğramadan. Depoyu doldur!",
  "tip.loyalty.title": "Sadakat kartı",
  "tip.loyalty.text": "Kartla müşteriler %6 daha yüksek fiyatları kabul eder — fiyatları biraz artırabilirsin. Eli boş gidenler de puanı daha az düşürür.",
  "tip.delivery.title": "Eve teslimat",
  "tip.delivery.text": "Gün içinde kasadaki telefon çalar, altta bir sipariş kartı çıkar. “Kabul et”e dokun: sipariş hazırlanır, kurye götürüp parayı getirir, hızlı teslimata da bahşiş gelir. 15 saniyede cevap vermezsen teslimat puanı düşer ve daha az ararlar.",
  "tip.register2.title": "Yeni kasa",
  "tip.register2.text": "Artık birden fazla kasan var. İlki senin, her yeni kasaya ise ayrı bir kasiyer gerekir (“Personel” sekmesi) — yoksa kapalı kalır. Kuyruk boş kasaya gider.",
  "tip.oven.title": "Ekmek fırını",
  "tip.oven.text": "Yan binada ekmek fırını açıldı. “Personel” sekmesinden fırıncı al — ekmeği kendisi pişirip raflara taşır. Ekmek kokusu varken ekmek iki kat daha sık satılır.",
  "tip.coffee.title": "Kahve dükkânı",
  "tip.coffee.text": "Yan binada kahve dükkânı açıldı. “Personel” sekmesinden barista al, çekirdek ve bardakları “Köşeler” sekmesinden takip et — yağmurda kahve daha çok satılır.",
  "tip.ownerTill.title": "Kasa senin",
  "tip.ownerTill.text": "İlk kasanın başında sen varsın. Kasaya dokunarak hesap yaparsın — ya da dükkânın altındaki sokağa, parmağına daha rahat gelir. Kasiyerler ikinci ve sonraki kasalara geçer, yedek kasiyer (“Küçük dükkân”dan itibaren) ise seninkine kalıcı olarak geçer — o zaman dokunuşların onu hızlandırır.",
  "tip.broke.title": "Boş kasa",
  "tip.broke.text": "Para yok, raflar bomboş — böyle hasılat da olmaz. Banka mal almak için kredi verir: “Gelişim” sekmesi → “Banka”. Faturalarla birlikte taksit taksit ödersin.",
  "tip.alone.title": "Tek başına olmaz",
  "tip.alone.text": "Dükkân büyüdü ama kasa, raflar ve depo hep sende: müşteriler gidiyor, puan artmıyor. “Personel” sekmesinden yardımcı al: reyoncu malları dizer, temizlikçi temizler, kasiyer ikinci kasaya geçer.",
  "tip.nightShift.title": "Gece vardiyası",
  "tip.nightShift.text": "Akşam 45 saniye daha çalışabilirsin: müşteri az ama kimse fiyata itiraz etmez.",
