  "tour.title": "Nine dükkânı gezdiriyor · {n}/{total}",
  "tour.next": "İleri",
  "tour.skip": "Geç",
  "tour.done": "Haydi!",
  "tour.replay": "Ninenin turu",
  "tour.replayNote": "Nine neyin nerede olduğunu yine gösterir",
  "tour.hello": "Merhaba yavrum! Gitmeden önce burada her şeyin nasıl işlediğini göstereyim. Uzun sürmez!",
  "tour.top": "Üstte — bugün hangi gün ve ne kadar paran var. Sabah hazırlanırsın, gündüz satış yaparsın, akşam hasılatı sayarsın.",
  "tour.today": "Bugünün önemlileri burada: sabah ne yapılacak, hava, kaç müşteri gelecek, kira ve elektrik ne zaman ödenecek.",
  "tour.buy": "“Alım” — malı buradan alırsın. “Eksikleri al”a dokun — neyin eksik olduğunu ben hesaplarım, en ucuz yerden alırım. Tedarikçiler zamanla kendileri indirim yapar, pazarlığa gerek yok.",
  "tour.warehouse": "“Salon” — üstte depo var: raflara sığmayan stok. Sabah boş yerlere kendisi dizilir; bozulmak üzere olanları indirime koy.",
  "tour.shelves": "“Salon”un aşağısında rafların var. Geliştirmek, tamir etmek ya da satmak için bir rafa dokun. Yeni raflar da burada alınır; fiyatlar “Alım”da.",
  "tour.extras": "“Köşeler” — kasada tatlılar, kahve, kendi fırının, bir kedi. Dükkân büyüyünce lazım olur.",
  "tour.staff": "“Personel” — yardımcıların. İlk kasada hep sen olursun; zamanla reyoncu, temizlikçi, bekçi ve yeni kasaların kasiyerleri gerisini üstlenir.",
  "tour.store": "“Gelişim” — dükkânı büyütme, kasalar, ekipman, reklam, faturalar ve benim komşulara borcum. Başarılar ve ayarlar üstteki 🏆 altında.",
  "tour.open": "Hazır olunca “Dükkânı aç”a dokun. Müşteriler raflardan malı alıp kasaya gelir: hesabı yapmak için kasaya ya da alttaki sokağa dokun.",
  "tour.hall": "Raf boş mu — dokun, depodan mal getir. Çöpleri ve su birikintilerini temizle, kovayı boşalt. Akşam ne kazandığını görürsün. Kolay gelsin, yavrum!",
  "onb.hello": "Yavrum, dükkân artık senin! Bak — geliyorlar bile.",
  "onb.shop": "Müşteriler malı raftan alıp kasaya getirir.",
  "onb.serve": "Hesabı yapmak için kasaya dokun!",
  "onb.sold": "Aferin! İşte ilk satışın.",
  "onb.road": "Kasaya uzanmana gerek yok — alttaki sokağa dokun, o da olur!",
  "onb.bye": "Gerisini sen halledersin, ben bağ evine gidiyorum. Akşam hasılatı sayarız!",
  "onb.stampTop": "Yaşasın!",
  "onb.stamp": "İlk satış",
  "onb.ok": "Anladım",
  "onb.new": "Yeni",
  "onb.tab.buy": "Sabahlar alım içindir. “Eksikleri al”a dokun — neyin eksik olduğunu ben hesaplarım.",
  "onb.tab.hall": "“Salon” — depo ve raflar. Geliştirmek, tamir etmek ya da satmak için rafa dokun.",
  "onb.tab.staff": "Tek başına yetişemiyor musun? “Personel”den yardımcı al.",
  "onb.tab.grow": "“Gelişim” — dükkânı büyüt, kasalar, reklam ve benim komşulara borcum.",
  "onb.tab.extras": "“Köşeler” — kasada tatlılar, kahve, kendi fırının ve bir kedi.",
  "tut.serve": "Bir müşteri bekliyor — kasaya dokun!",
  "tut.restock": "Bu raf boşaldı. Depodan mal getirmek için ona dokun.",
  "tut.summary": "Gün böyle geçti: hasılat ve müşteriler. “Sonraki gün”e dokun — sabah alım yaparız.",
