  "bigday.caption": "📺 Son dakika",
  "bigday.anchor": "Alina, Şehir Haberleri",
  "bigday.ok": "Anladım, işe koyulalım!",
  "bigday.summary": "Özel gün",
  "bigday.heatwave.title": "Rekor sıcak",
  "bigday.heatwave.news": "Son dakika! Şehirde rekor sıcak: gölgede 41°C. Doktorlar akşama kadar zorunlu olmadıkça dışarı çıkılmamasını istiyor.",
  "bigday.heatwave.hint": "Bugün çok daha az müşteri gelecek. Gelenler su, meyve suyu ve dondurma ister.",
  "bigday.frost.title": "Dondurucu ayaz",
  "bigday.frost.news": "Dikkat! Hava −35°C'ye kadar düştü. Okullar tatil, sakinlerden evde kalmaları isteniyor.",
  "bigday.frost.hint": "Az müşteri gelecek. Doyurucu şeyler alırlar: et, mantı, patates ve ekmek.",
  "bigday.flood.title": "Sel",
  "bigday.flood.news": "Son dakika! Sağanaklardan sonra nehir taştı, sokakları su bastı. Kurtarma ekipleri zorunlu olmadıkça dışarı çıkılmamasını istiyor.",
  "bigday.flood.hint": "Az müşteri gelecek. Su, ekmek ve temizlik ürünleri lazım.",
  "bigday.quake.title": "Deprem",
  "bigday.quake.news": "Dikkat! Sismologlar sarsıntılar kaydediyor. Panik yok: yüksek raflardan ve camlardan uzak durun.",
  "bigday.quake.hint": "Az müşteri gelecek, sarsıntılar da bazı malları raftan düşürüp kıracak.",
  "bigday.carnival.title": "Karnaval!",
  "bigday.carnival.news": "Harika haber! Bugün sokağımızdan yaz karnavalı geçecek: tüylü dansçılar, davullar ve platformlar — tıpkı Rio de Janeiro'daki gibi!",
  "bigday.carnival.hint": "İki kat kalabalık! Herkes acıkacak ve susayacak: su, meyve suyu, dondurma. Rafları doldurmaya yetiş.",
  "bigday.parade.title": "Bando geçidi",
  "bigday.parade.news": "Bugün Şehir Günü! Sokağımızdan bando geçidi geçecek, arkasından da bayraklı, balonlu şehir halkı.",
  "bigday.parade.hint": "Neredeyse iki kat kalabalık. Çiçek, meyve suyu ve su iyi satar.",
  "popup.quake": "Sarsıntı! Kırılan: {n}",
  "rare.queen": "Kraliçe",
  "rare.pirate": "Korsan",
  "rare.clown": "Palyaço",
  "rare.knight": "Şövalye",
  "rare.alien": "Uzaylı",
  "rare.magician": "Sihirbaz",
  "rare.viking": "Viking",
  "rare.superhero": "Süper kahraman",
