  "rare.ninja": "Ninja",
  "bigday.blackout.title": "Elektrik yok",
  "bigday.blackout.news": "Son dakika! Trafoda arıza: tüm mahalle öğlene kadar elektriksiz. Ekipler çalışıyor.",
  "bigday.blackout.hint": "Yarım gün elektrik yok: kasa elle ve yavaş hesaplar, dolaplar ısınır — içindeki mallar bir gün yaşlanır. Müşteri biraz az.",
  "bigday.filming.title": "Film çekimi!",
  "bigday.filming.news": "Günün haberi: tam dükkânının önünde yeni bir filmin sahnesi çekiliyor! Yıldızlar, kameralar, meraklı kalabalık.",
  "bigday.filming.hint": "Çok meraklı gelecek — herkes bir şey içip atıştırmak isteyecek. Dükkân da kadraja girecek: yarın bedava reklam.",
  "bigday.marathon.title": "Şehir maratonu",
  "bigday.marathon.news": "Bugün şehir maratonu var! Binlerce koşucu dükkânının önünden geçecek.",
  "bigday.marathon.hint": "Bir buçuk kat kalabalık. Koşucular ve taraftarlar su ve meyve suyunu silip süpürecek.",
  "bigday.tourbus.title": "Tur otobüsü",
  "bigday.tourbus.news": "Turistler geliyor! Gezi otobüsü tam dükkânının önünde duracak.",
  "bigday.tourbus.hint": "Öğleye doğru otobüsten bir anda {n} turist inecek — kasa kapış kapış olacak. Dondurma, su ve tatlı severler.",
  "bigday.starfall.title": "Meteor yağmuru",
  "bigday.starfall.news": "Bu gece yılın en parlak meteor yağmuru! Gökbilimciler dışarı çıkıp dilek tutmayı öneriyor.",
  "bigday.starfall.hint": "Akşam bütün şehir sokakta: gece vardiyan varsa gece iki kat müşteri gelir.",
  "bigday.pigeons.title": "Güvercin istilası",
  "bigday.pigeons.news": "Tuhaf haber: şehre kocaman güvercin sürüleri geldi. Kuşlar dükkânlara ve kafelere dalıyor!",
  "bigday.pigeons.hint": "Güvercinler salona girip müşterileri korkutacak. Kovmak için kuşa dokun.",
  "bigday.roadworks.title": "Yol çalışması",
  "bigday.roadworks.news": "Dikkat! Dükkânının önünde yol çalışması başlıyor. Çalışma {n} gün sürecek.",
  "bigday.roadworks.hint": "Kazı sürerken müşteri az, ama baretli işçiler öğle yemeği almaya gelir: ekmek, börek, mantı, su.",
  "bigday.sanitary.title": "Sağlık denetimi baskını",
  "bigday.sanitary.news": "Son dakika! Sağlık denetçileri mahalledeki tüm dükkânlara habersiz denetim yapıyor.",
  "bigday.sanitary.hint": "Bugün sana bir denetçi gelecek. Çöpleri ve su birikintilerini temizle, tarihi geçmiş malları at — pislik cezaya yol açar.",
  "bigday.wedding.title": "Yan tarafta düğün",
  "bigday.wedding.news": "İyi haber: yandaki kafede bugün düğün var! Gelin ve damat akşam için senden ikram siparişi verdi.",
  "bigday.wedding.hint": "Sipariş akşam alınacak: {order}. Normalden pahalıya öderler, siparişin tamamı puanını da artırır.",
  "bigday.epidemic.title": "Tehlikeli hastalık",
  "bigday.epidemic.news": "Dikkat! Şehirde tehlikeli bir hastalık salgını var. Doktorlar maske takılmasını ve evden mümkün olduğunca az çıkılmasını istiyor.",
  "bigday.epidemic.hint": "{n} gün boyunca müşteri az, ama herkes stok yapıyor: sabun, temizlik ürünleri, su, mantı ve patates.",
  "bigday.dayOf": "{icon} {title}: {n}/{of}. gün",
