  "giant.build.news": "Mahalle haberi: ulusal zincir Giant, tam dükkânının karşısında dev bir hipermarket inşa etmeye başladı! {n} gün sonra açılıyor.",
  "giant.build.hint": "🕴️ Eduard: “Nasıl hesap yaptıklarını bilirim. Puanını 4.5★ tut, reklam ver, sadakat kartı çıkar, fırından kendi ürünlerini sat — müşterilerin hiçbir yere gitmez.”",
  "giant.battle.news": "Giant açıldı! İndirimler, balonlar, otoparkta kuyruklar. Mahallenin yarısı ne var ne yok diye bakmaya gitti.",
  "giant.battle.hint": "Müşteri savaşı {n} gün sürecek. {target} 💰 kazan ve puanını {r}★ veya üstünde tut. Başarırsan Giant kapanır.",
  "giant.won.news": "Sansasyon! Giant hipermarketi kapanıyor: mahalle sakinleri yandaki şirin dükkânı seçti. Zincirin müdürü yenilgiyi kabul etti.",
  "giant.won.hint": "Giant hipermarketini yendin! Ödül +{reward} 💰 ve +0.5★, mahalle şöhreti de sonsuza dek +%{fame} müşteri getirir.",
  "giant.lost.news": "Giant dayandı: iki haftada çok müşteri çaldı. Ama zincir hasılattan memnun değil ve mahalle için yeni bir savaş vaat ediyor.",
