  "staffEvent.quarrel.text": "{name} ile {name2} vardiya yüzünden kavga etti, konuşmuyorlar. Herkese pizza ısmarlayıp onları barıştırır mısın ({n} 💰)? Barıştırırsan ikisi de hevesle birkaç gün daha hızlı çalışır.",
