  "staffEvent.quarrel.no": "Kendileri çözsün",
  "staffEvent.idea.text": "“Girişe parlak etiketli bir günün ürünü koysak? İnsanlar içeri girer!” Desteklersen dükkân popülerleşir, fikrin sahibi de hevese gelir.",
