  "kitchen.note": "Hazır yemek girişteki “Yemek” rafında durur — müşteriler kasaya giderken bir porsiyon alır. Satılmayan gece atılır (buzdolabında bir kısmı sabaha kalır). Rafta: {n}/{max}.",
