  "kitchen.chef": "Aşçı {name} mutfağı yönetiyor: mutfak malzemeyi tedarikçilerden alır (kasadan), aşçı pişirip tabakları “Yemek” rafına taşır — akşama kadar satılacak kadar.",
  "kitchen.noChef": "Aşçı yoksa mutfak her sabah dükkânın mallarından (önce depo, sonra raflar) kendi pişirir — «Yemek» rafına sığdığı kadar. Aşağıdaki düğmelerle daha fazla pişirebilirsin. Bir aşçı (“Personel” sekmesi) bütün gün pişirir, malzemeyi de kendisi alırdı.",
