  "tale.title": "{icon} {name} · bölüm {n}/{of}",
  "tale.need.money": "{n} 💰 gerekli",
  "tale.need.product": "{n} adet stok gerekli",
  "tale.anya.name": "Öğrenci Anya",
  "tale.anya.0.text": "“Merhaba! Ben Anya, iktisat okuyorum. Bursum gecikti… Rafları dizmene yardım etsem, karşılığında bir ekmek verir misin?”",
  "tale.anya.0.0": "Tabii, al ekmeği",
  "tale.anya.0.1": "Üzgünüm, bugün olmaz",
  "tale.anya.1.text": "Anya yine geldi: “O gün beni kurtardın! Sınavlar yaklaşıyor, ders kitabı da 300. Borç verir misin? İlk maaşımdan öderim, söz.”",
  "tale.anya.1.0": "Al, 300 💰",
  "tale.anya.1.1": "Üzgünüm, veremem",
  "tale.anya.2.text": "Anya'nın yüzü gülüyor: bütün sınavlar pekiyi! Borcunu iki katı ödüyor — 600 💰 — ve bütün sınıfını getirmiş: “Şehrin en iyi kalpli dükkâncısı burada!”",
  "tale.anya.2.0": "Sağ ol, Anya!",
  "tale.anya.3.text": "Anya müjdeyi vermeye uğradı: sınavları geçmiş! Kitabı kütüphaneden bulmuş. Birkaç sınıf arkadaşını da getirmiş.",
  "tale.anya.3.0": "Çok sevindim!",
  "tale.anya.4.text": "Anya mezun oldu ve yandaki bankada işe girdi. “Bütün iş arkadaşlarıma seni anlattım — artık öğle yemeğini sadece burada alacaklar!”",
  "tale.anya.4.0": "Harika haber!",
  "tale.wedding.name": "Damat Timofey",
  "tale.wedding.0.text": "Bir genç elinde yüzük kutusunu evirip çeviriyor: “Ben Timofey. Katya'yla senin kuyruğunda tanıştık! Ona tam kapının önünde evlenme teklif etmek istiyorum. Vitrini süslemeye yardım eder misin? Balonlar, ışıklar — 200 civarı.”",
  "tale.wedding.0.0": "Süsleyelim! (−200 💰)",
  "tale.wedding.0.1": "Burası dükkân, nikâh salonu değil",
  "tale.wedding.1.text": "Katya “evet” dedi! Vitrinin önünde mahallenin yarısı alkışladı. Timofey: “Düğün 5 gün sonra. Düğün ekmeği ve sandviçler için 30 somun ekmek lazım — iki katını öderiz!”",
  "tale.wedding.1.0": "Anlaştık!",
  "tale.wedding.1.1": "Yetiştiremeyiz, kusura bakma",
  "tale.wedding.2.text": "Düğün günü! Timofey takım elbisesiyle siparişi almaya geldi: 30 somun ekmek.",
  "tale.wedding.2.0": "Buyur siparişin!",
  "tale.wedding.2.1": "Kusura bakma, yetiştiremedik…",
  "tale.wedding.3.text": "Timofey ile Katya balayından döndü: “Artık sadece buradan alışveriş yapıyoruz. Düğündeki bütün misafirlere de anlattık!”",
  "tale.wedding.3.0": "Mutluluklar!",
  "tale.busker.name": "Sokak müzisyeni Gosha",
  "tale.busker.0.text": "Kapıda gitarlı bir genç: “Ben Gosha. Dükkânının önünde çalabilir miyim? İnsanların keyfi yerine gelir — sana da müşteri gelir.”",
  "tale.busker.0.0": "Çal!",
  "tale.busker.0.1": "Gürültü istemem",
  "tale.busker.1.text": "Gosha'nın kapında şarkı söylediği video bir milyon izlendi! Bir blogger tam dükkânın içinde çekim yapmak istiyor.",
  "tale.busker.1.0": "Buyurun çekin!",
  "tale.busker.1.1": "Hayır, işi aksatır",
  "tale.busker.2.text": "Gosha bir grup kurdu ve seni ilk konserlerine çağırıyor. Sponsor lazım: 1000 💰 — ve dükkânın şehrin bütün afişlerinde olacak.",
  "tale.busker.2.0": "Sponsor ol (−1000 💰)",
  "tale.busker.2.1": "Bol şans, Gosha!",
