  "contest.finale.caption": "🏆 Final",
  "contest.finale.1": "Dükkânımıza bakıyorum da gözlerime inanamıyorum. Bir zamanlar ekmekle elmanın satıldığı minicik büfemdi…",
  "contest.finale.2": "Bütün komşulara söylüyorum: en sevdiğim dükkân burası! Şimdi bir de kupası var.",
