  "nightGuest.taxi.0": "Sabaha kadar vardiya… bir su lütfen!",
  "nightGuest.taxi.1": "Beş dakika mola, sonra yine direksiyona",
  "nightGuest.student.0": "Sınav haftası! Mantı ve meyve suyu lazım",
  "nightGuest.student.1": "Dönem ödevi kendi kendini yazmaz…",
  "nightGuest.doctor.0": "Nöbetten yeni çıktım. Sağlıklı bir şey?",
  "nightGuest.doctor.1": "24 saattir ayaktayım — elma ve meyve suyu",
  "nightGuest.guard.0": "Gece devriyesi, midem de bomboş",
  "nightGuest.guard.1": "Karşıdaki depoyu bekliyorum. Ekmek var mı?",
  "nightGuest.musician.0": "Konser bitti ama enerjim hâlâ yerinde!",
  "nightGuest.musician.1": "Size bir şey çalayım mı?",
  "nightGuest.insomniac.0": "Uyku tutmuyor… ılık süt iyi gelir",
  "nightGuest.insomniac.1": "Bizim zamanımızda dükkânlar gece açık olmazdı!",
  "nightGuest.lovers.0": "Gece ikide çiçek — var mı?",
  "nightGuest.lovers.1": "Şşş… ona sürpriz",
  "nightGuest.vampire.0": "Domates suyu? Sadece domates…",
  "nightGuest.vampire.1": "Işıklarınız pek parlak… neyse",
  "nightStory.studentDebt.title": "🎓 Parasız öğrenci",
  "nightStory.studentDebt.text": "“Bursum üç gün sonra yatıyor ama karnım şimdi aç. {item} veresiye alabilir miyim? İki katını öderim, söz!”",
  "nightStory.studentDebt.note": "Genelde öderler — bir de arkadaşlarını getirirler. Ama her zaman değil.",
  "nightStory.studentDebt.yes": "Al, afiyet olsun",
  "nightStory.studentDebt.no": "Üzgünüm, veresiye yok",
  "nightStory.taxiTea.title": "🚕 Üşümüş bir taksici",
  "nightStory.taxiTea.text": "“On dakika burada ısınabilir miyim? Ben de yolculara dükkânını anlatırım — bütün gece açık ve güler yüzlü.”",
  "nightStory.taxiTea.note": "Yarın %6 daha fazla müşteri.",
  "nightStory.taxiTea.yes": "Tabii, ısının",
  "nightStory.taxiTea.no": "Burası bekleme salonu değil",
  "nightStory.sleepyDoctor.title": "🩺 Bir doktor kasada uyuyakaldı",
  "nightStory.sleepyDoctor.text": "24 saatlik nöbetten çıkan bir doktor kasanın yanına oturdu — ve elinde sepetle uyuyakaldı.",
  "nightStory.sleepyDoctor.note": "Dinlenince bol alışveriş yapar, meslektaşlarına da anlatır.",
  "nightStory.sleepyDoctor.yes": "Uyusun, üstüne battaniye ört",
  "nightStory.sleepyDoctor.no": "Uyandır: “Burada uyunmaz!”",
  "nightStory.busker.title": "🎸 Kapıda bir müzisyen",
  "nightStory.busker.text": "“Vardiya bitene kadar kapında çalabilir miyim? İnsanların keyfi yerine gelir, sana da müşteri gelir.”",
  "nightStory.busker.note": "%30 daha fazla gece müşterisi ve bahşiş.",
  "nightStory.busker.yes": "Çal!",
  "nightStory.busker.no": "Olmaz, insanlar uyuyor",
  "nightStory.thanks": "Teşekkürler!",
