  "kiosks.title": "🖥 Self servis kasalar",
  "kiosks.note": "Küçük sepetli müşteriler ödemeyi kendileri yapar — kasadaki kuyruk kısalır, insanlar dükkâna daha istekli girer. Model bütün kiosklar için ortak: yenisi daha hızlı, “hata” daha az, “okutmayı unutulan” ürün daha az.",
