  "staffTab.reliefOn": "Kasanda yedek kasiyer var: bütün gün kendisi okutur. Kasaya dokun, daha hızlı okutsun — sen de başka işlere bak.",
  "drama.teaser": "Sonya sana bir şey söylemek istiyordu… Yarın uğra — seni bekleyecek.",
  "drama.night.before.1": "Baba, yine mi geç kalacaksın? Antrenin ışığını açık bırakırım.",
  "drama.night.before.2": "Dört akşamdır yemeği tek başıma yiyorum. Öylesine, sayıyorum sadece.",
  "drama.night.before.3": "Bir haftadır akşamları seni görmüyorum. Dükkân benim neye benzediğimi hatırlıyor mu bari?",
