  "decor.holidayWhen.march8": "8 Mart civarı",
  "decor.packNote": "Sadece “{pack}” olarak satılır: {items}. Bir kez alınır, sonsuza dek senin.",
  "live.newyear.card.1": "1 Aralık! Dükkân yavaş yavaş süsleniyor — kışın ilk günü kutlu olsun!",
  "live.newyear.card.2": "Dışarısı kar, içerisi mandalina kokuyor. İyi günler!",
  "live.newyear.card.3": "Bugün kasa daha sık çınlasın, için de sıcacık olsun.",
  "live.newyear.card.4": "Müşteriler soğuktan yanakları kızarmış geliyor — her birine gülümse.",
  "live.newyear.card.5": "Işıkları asıp çaydanlığı ocağa koymanın tam zamanı.",
  "live.newyear.card.6": "Kar ayak altında gıcırdıyor — demek gerçek kış geldi. Sıcacık bir gün dilerim!",
  "live.newyear.card.7": "Aralığın bir haftası geride kaldı! Her gün uğradığın için teşekkürler.",
  "live.newyear.card.8": "Küçük bir dilek tut — yılbaşına kadar gerçekleşmeye vakti var.",
  "live.newyear.card.9": "Birileri şimdiden hediye seçiyor. Sana da uğrasınlar!",
  "live.newyear.card.10": "Bir fincan kakao ve vitrinin sıcak ışığı — işte huzur bu.",
  "live.newyear.card.11": "Bugün tek bir yoğurdun bile tarihi geçmesin!",
  "live.newyear.card.12": "Kış akşamında vitrin bir başka parlıyor.",
  "live.newyear.card.13": "Nine diyor ki aralıkta ekmek bile bayram kokar.",
  "live.newyear.card.14": "Camlarda buz desenleri. Güzel, değil mi?",
  "live.newyear.card.15": "Aralığın iki haftası geride kaldı. İyi ki bizimlesin!",
  "live.newyear.card.16": "Yılbaşına yolun yarısı! Al, küçük bir hediye.",
  "live.newyear.card.17": "Bugün müşteriler güler yüzlü, kuyruklar kısa olsun.",
  "live.newyear.card.18": "Mandalina, çam ağacı, ışıklar — bayram kapıyı çalıyor.",
  "live.newyear.card.19": "Kedi de yılbaşını bekliyor. Özellikle de akşam yemeğindeki balığı.",
  "live.newyear.card.20": "Kış günleri kısa — güzel anlar uzun olsun.",
  "live.newyear.card.21": "Yılın en uzun gecesi. Bundan sonra hep daha aydınlık!",
  "live.newyear.card.22": "Üç hafta bitti. Bayrama az kaldı!",
  "live.newyear.card.23": "Bugün en az bir hoş sürpriz yaşansın.",
  "live.newyear.card.24": "Ağacın altında hediyeler birikiyor. Sana da bir kart var!",
  "live.newyear.card.25": "Yılbaşına bir hafta! Tam mucize zamanı.",
  "live.newyear.card.26": "Birisi kapının önünde kardan adam yapıyor. Kış tüm hızıyla sürüyor!",
  "live.newyear.card.27": "Yeni yılda dükkân daha da sıcacık olsun.",
  "live.newyear.card.28": "Az kaldı. Bayram telaşında kendine iyi bak!",
  "live.newyear.card.29": "Salatalar, mandalinalar, ışıklar — ve bir tutam sihir.",
  "live.newyear.card.30": "Yarın yılın son günü. Neler başardığını bir hatırla!",
  "live.newyear.card.31": "Mutlu yıllar! Bütün aralık bizimle olduğun için teşekkürler. Yeni yılın sıcacık geçsin!",
  "live.feb23.card.1": "Vatan Savunucuları Günü kutlu olsun! Yanında hep sana destek olacak biri olsun.",
  "live.feb23.card.2": "Sağlık, huzur ve yanında güvenilir bir omuz!",
  "live.feb23.card.3": "Bayramın kutlu olsun! Cesaret ve iyilik hep el ele yürüsün.",
  "live.march8.card.1": "Bahar kapıda! Her gün sıcak ve aydınlık olsun.",
  "live.march8.card.2": "Mimoza bahar kokuyor. Keyfin de onun kadar güneşli olsun!",
  "live.march8.card.3": "8 Mart Dünya Kadınlar Günü kutlu olsun! Etrafın çiçek, gülümseme ve güzel sözlerle dolsun.",
