  "gift.treat.7": "kocaman ballı pasta",
  "letter.grandma.1": "Yavrum, nasılsın? Öğle yemeğini atlamıyorsun ya? Ufak tefek masraflar için biraz koyuyorum — kendine haşhaşlı çörek al.",
  "letter.grandma.2": "Bütün akşam, küçükken tezgâhın arkasına saklandığın aklıma geldi. Şimdi dükkânı sen işletiyorsun! Seninle gurur duyuyorum. İçinde ufak bir şey var.",
  "letter.grandma.3": "Üçüncü kattaki komşu ekmeğini övdü. Köyümüzdeki gibi yumuşacık, diyor. Al, dükkân için.",
  "letter.grandma.4": "Mum ışığında yazıyorum — elektrik yine kesildi. Fiyatları şişirme, iyi insanlar unutmaz. Biraz koydum, itiraz etme.",
  "letter.grandma.5": "Sana çorap ördüm, hafta sonu getiririm. Şimdilik zarfta biraz para var, kasa daha neşeli çınlasın.",
  "letter.grandma.6": "Televizyonda yağmur yağacak dediler. Kapının yanına şemsiye koy! Bu da ne olur ne olmaz diye.",
  "letter.grandma.7": "Deden derdi ki: “Dükkân her gün gelenlerle ayakta durur.” Sen onlar için çabala, ben de senin için. Öperim.",
  "letter.grandma.8": "Börekler hiç bu kadar güzel olmamıştı! Postayla yollanmıyor, ne yazık. Yollanabileni yolluyorum — çaya bir şey al.",
  "letter.valya.1": "Selam komşu! Dün gece geç saate kadar ışığın yanıyordu. Kendini yorma. Bir şey olursa duvara vur.",
  "letter.valya.2": "Pazarda duydum: süte yakında zam geliyormuş. Komşu olarak söylüyorum, önceden bil diye.",
  "letter.valya.3": "Kedimin yine iştahı yok, ama senin balığını silip süpürüyor! Yani bekle beni — balık için gelirim.",
  "letter.valya.4": "Dün kuyruğun köşeyi dönüyordu. Öyle sevindim ki! Bir kasiyer daha mı alsan?",
  "letter.valya.5": "Kasanın yanındaki çiçekler harika. Kız kardeşime aldım, hâlâ pazardan sanıyor. Söylemem!",
  "letter.valya.6": "Not bırakıyorum — sabahları hep meşgulsün. Bana taze ekmek ayırdığın için sağ ol. Küçük şey ama hoş.",
  "letter.sonya.1": "Baba, resim kursu portfolyom için dükkânımızı çizdim. Kedi senden daha önemli çıktı. Alınma.",
  "letter.sonya.2": "Baba, sosyal bilgilerde küçük işletmeler hakkında kompozisyon ödevi verdiler. Seninle röportaj yapabilir miyim? Yalnız ciddi cevap ver.",
  "letter.sonya.3": "Baba, cumartesi kasada durabilir miyim? Senden hızlı hesap yapıyorum, denendi.",
  "letter.sonya.4": "Baba, dükkâna sosyal medyada sayfa açtım. Şimdiden kırk takipçi. Teşekküre gerek yok.",
  "letter.sonya.5": "Baba, yine mi geç kalıyorsun? Yemek buzdolabında, üstüne yazdım — yoksa ninem yer.",
  "letter.sonya.6": "Baba, meslek rehberliğinde ne olmak istediğimi sordular. Dedim ki: daha bilmiyorum ama sıkıcı bir yetişkin kesinlikle olmayacağım. Sen sayılmazsın.",
  "letter.regular.1": "Bu {item} için sağ ol — Giant'takinden iyi, valla. Bil diye yazıyorum: ben senin müşterinim.",
  "letter.regular.2": "Dün uğradım ama meşguldün. Şunu demek istedim: dükkânın ev gibi. Yarın yine gelirim.",
  "letter.regular.3": "Torunuma küçük dükkânından bahsettim — şimdi o da bakkal olmak istiyor. Böyle devam!",
  "letter.regular.4": "Kapının altından not bırakıyorum: senin {item} benim zaafım. Yeter ki fiyatı artırma, anlaştık mı?",
  "letter.regular.5": "Başka mahallede kız kardeşime gittim — orada böyle bir dükkân yok. Senin kasanı özledim, düşünsene!",
