  "hood.mural": "Duvar resmi",
  "hood.mural.desc": "Ressamlar meydanın yanındaki duvarı boyuyor: güneş, çiçekler ve elinde somunla bir nine. Müdavimler sokaklarıyla gurur duyar.",
  "hood.benches": "Banklı meydan",
