  "hood.fir": "Meydanda çam ağacı",
  "hood.fir.desc": "Meydanda kocaman bir çam. Kışın süslenir: toplar, ışıklar ve yıldız.",
  "hood.fountain": "Gölet kenarında fıskiye",
  "hood.fountain.desc": "Parktaki gölet kıyısında fıskiye: yazın bütün mahalle orada gezer.",
  "hood.playground": "Çocuk parkı",
  "hood.playground.desc": "Parkta kaydırak, salıncak ve kum havuzu. Çocuklu aileler sık alışveriş yapar.",
  "hood.facades": "Komşulara yeni cephe",
