  "echo.head": "{icon} Yankı: “{title}”",
  "echo.hello": "Beni hatırladınız mı?",
  "echo.later": "🔁 Bu hikâye geri dönecek…",
  "echo.ok.good": "Ne güzel!",
  "echo.ok.bad": "Eh… Ders oldu",
  "echo.drop": "müşteri −%{p} · {d} gün",
  "echo.boostLine": "🔁 Yankı: müşteri +%{p}, {n} gün daha",
  "echo.dropLine": "🔁 Yankı: müşteri −%{p}, {n} gün daha",
  "tip.echo.title": "Kararların yankısı",
  "tip.echo.text": "Sahneler unutulmaz. Bir iki hafta sonra kahramanları geri döner — minnetle ya da kırgınlıkla: ne ekersen onu biçersin.",
  "skit.robbery.confess.1": "Çantayı geri ver ve git. Bu seferlik affediyorum",
  "skit.robbery.forgive": "Çantam sapasağlam! Peki… madem kendisi itiraf etti, gitsin. Belki adam olur.",
  "echo.galina": "Benim, Galina Petrovna — çantalı teyze! Bütün mahalle artık nasıl bir dükkân sahibi olduğunuzu biliyor. Buyurun, size börek yaptım!",
  "echo.denis": "Gitmesine izin verdiğin kapüşonlu genç Denis'i hatırlıyor musun? Kendisi geldi: “Dürüstçe çalışmak istiyorum. Beni reyoncu olarak alır mısınız? Çok bir şey istemem.”",
  "echo.denis.0": "Reyoncu olarak al: ayda {n} 💰 (normalde {full})",
  "echo.denis.1": "Şimdi değil, ama kolay gelsin",
  "echo.denis.2": "Yer yok — girişi tamir etmeye yardım etsin",
  "echo.wrongCourier": "Hırsız dediğin kurye Ruslan'ı hatırlıyor musun? Unutmadı: mahalledeki bütün kuryelere anlattı, artık siparişleri senin önünden geçip gidiyor.",
  "echo.wrongPainter": "Haksız yere suçladığın boyacı Styopa'yı hatırlıyor musun? Bütün ekibi artık başka dükkânda öğle yemeği yiyor — ve herkese nedenini anlatıyor.",
  "echo.dogClub": "Sucukla çağırdığınız Simit'i ve Tyoma'yı hatırlıyor musun? Köpek çiftliğinin sahibi hikâyeyi duymuş — ve bütün köpek kulübünü sana getirdi!",
  "echo.bublik": "Benim, Tyoma! Bakın Simit ne kadar büyüdü! Artık her gün önünüzden geçiyoruz, annem de sütü sadece buradan alıyor.",
  "echo.tyomaCold": "Köpeği kaçan Tyoma'yı hatırlıyor musun? Onu başından savmıştın. Annesi bunu veli grubunda anlattı…",
  "echo.sergeant": "Viktor'u ve sahte banknotunu hatırlıyor musunuz? Onun sayesinde bütün çeteyi yakaladık! Karakoldan bir teşekkür belgesi — ve ödül.",
  "echo.viktor": "Viktor'u ve sahte banknotunu hatırlıyor musun? Komşu mahallede yakalanmış — Komiser Kovalyov para üstünün bir kısmını geri getirdi.",
  "echo.bakery": "Poğaçalarımı hatırladınız mı? Durağın yanında kendi fırınımı açtım! İlk tepsi sizin, hediye. Herkese de nerede başladığımı anlatıyorum!",
  "echo.stale": "Lyoşa'nın poğaçalarını hatırlıyor musun? Komşular hâlâ şaka yapıyor: “Poğaçayla çivi çakılan yer orası değil mi?”",
  "echo.classTrip": "Anna Sergeyevna size bir kart gönderdi! Bu hafta da bütün sınıf “Bir dükkân nasıl çalışır” gezisine geliyor — velilerle birlikte!",
  "echo.roses": "Anna Sergeyevna için alınan gülleri hatırlıyor musun? Bir hafta hapşırdı. Veli grubunda kimin önerdiğini soruyorlar — herkes de biliyor.",
  "echo.sequel": "Yayını hatırladınız mı? Takipçilerim devamını istiyor! Bugün “En sevdiğim dükkânda bir gün” çekiyorum — misafirlere hazır olun!",
  "echo.roast": "Karina'nın yayınını hatırlıyor musun? Bir kesit paylaştı: “Dükkân sahibi takipçilere kaba davranıyor.” Yüz bin izlenme ve yerden yere vuran yorumlar…",
  "echo.couriers": "Sağanağı hatırladınız mı? Artık bütün vardiyamız öğle yemeğini sizde yiyor — yağmurda da sıcakta da. Buyurun, bu çocuklardan!",
  "echo.scarf": "Ruslan bir paket getirdi: sağanakta ilaçlarını götürdüğün beşinci kattaki nine sana atkı örmüş! Bütün komşularına da seni anlatıyor.",
  "echo.dispatcher": "Sağanağı ve geciken ilaçları hatırlıyor musun? Operatör Oleg artık kuryeleri yemeğe başka yerlere gönderiyor.",
  "echo.fired": "Ruslan'ı hatırlıyor musun? O sağanaktan sonra kovuldu. Artık çantasız geliyor — gülümsemesi de yok.",
