  "letter.staff.1": "Fırın açıldı! Şimdilik küçük, üç masa. Ekmek pişiriyorum ve şafak sökmeden kamyon boşalttığımız günleri hatırlıyorum. Uğra — benden. Dükkânımızdaki her şey için teşekkürler!",
  "letter.staff.2": "Okuyorum! Zor ama keyifli. Sınıf arkadaşlarıma dükkânımızı anlatıyorum — bir dükkânın bu kadar sıcak olabileceğine inanmıyorlar. Gitmeme izin verdiğin için teşekkürler.",
  "letter.staff.3": "Yerleştik. Burada da bir dükkân var ama aynı değil — ne kedi var ne de büyükannenin börekleri. Herkese selam söyle, kediyi de kulağının arkasından kaşı.",
  "letter.staff.4": "Dinleniyorum, domates dikiyorum. Torunlara dükkânımızı anlatıyorum — düşünün, onca vardiya! Bir gün çok yoğun olursa beni çağır, nasıl yapıldığını gösteririm.",
  // Своя марка на полках (game/lines.ts) и обрыв связи при подкачке (platform/lazy.ts).
